function validate([firstString, secondString]) {
  if (typeof firstString !== 'string' || firstString.length < 1 || firstString.length > 200000) return 'firstString needs 1 to 2 * 10^5 letters.';
  if (typeof secondString !== 'string' || secondString.length < 1 || secondString.length > 200000) return 'secondString needs 1 to 2 * 10^5 letters.';
  if (!/^[a-z]+$/.test(firstString) || !/^[a-z]+$/.test(secondString)) return 'Both strings use only lowercase letters.';
  return null;
}

