function countQuadruples(firstString, secondString) {
  const first = new Array(26).fill(-1);
  const last = new Array(26).fill(-1);
  for (let i = firstString.length - 1; i >= 0; i--) {
    first[firstString.charCodeAt(i) - 97] = i;
  }
  for (let a = 0; a < secondString.length; a++) {
    last[secondString.charCodeAt(a) - 97] = a;
  }
  let best = Infinity;
  let count = 0;
  for (let c = 0; c < 26; c++) {
    if (first[c] === -1 || last[c] === -1) {
      continue;
    }
    const diff = first[c] - last[c];
    if (diff < best) {
      best = diff;
      count = 1;
    } else if (diff === best) {
      count++;
    }
  }
  return count;
}

