function countQuadruples(firstString, secondString) {
  // List every valid quadruple directly and count those with the smallest j - a.
  const diffs = [];
  for (let i = 0; i < firstString.length; i++)
    for (let j = i; j < firstString.length; j++)
      for (let a = 0; a < secondString.length; a++)
        for (let b = a; b < secondString.length; b++)
          if (firstString.slice(i, j + 1) === secondString.slice(a, b + 1)) diffs.push(j - a);
  if (!diffs.length) return 0;
  const least = Math.min(...diffs);
  return diffs.filter(d => d === least).length;
}

