function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const make = (length, letters) => {
    let text = '';
    for (let k = 0; k < length; k++) text += letters[Math.floor(rand() * letters.length)];
    return text;
  };
  const all = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'small') {
    const pool = rand() < 0.15 ? ['ab', 'cd'] : [all.slice(0, int(1, 4)), all.slice(0, int(1, 4))];
    return [make(int(1, 6), pool[0]), make(int(1, 6), pool[1])];
  }
  // Large: a shared block of distinct letters inside both strings makes several letters tie.
  const letters = all.slice(0, int(3, 26));
  const shuffled = letters.split('');
  for (let k = shuffled.length - 1; k > 0; k--) {
    const r = Math.floor(rand() * (k + 1));
    [shuffled[k], shuffled[r]] = [shuffled[r], shuffled[k]];
  }
  const block = shuffled.join('').slice(0, int(1, letters.length));
  const firstString = rand() < 0.5 ? block + make(int(8000, 9900), letters) : make(int(8000, 10000), letters);
  const secondString = rand() < 0.5 ? make(int(8000, 9900), letters) + block : make(int(8000, 10000), letters);
  return [firstString, secondString];
}
